import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('clinica.db');

// Tabelas com o relacionamento: consultas guarda paciente_id apontando
// para pacientes.id (1:N — um paciente tem muitas consultas)
db.exec(`CREATE TABLE IF NOT EXISTS pacientes (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL
)`);
db.exec(`CREATE TABLE IF NOT EXISTS consultas (
  id INTEGER PRIMARY KEY,
  paciente_id INTEGER NOT NULL,
  dia TEXT NOT NULL,
  hora TEXT NOT NULL
)`);

// INNER JOIN: só consultas com paciente existente
const comPaciente = db.prepare(`
  SELECT pacientes.nome, consultas.dia, consultas.hora
  FROM consultas
  INNER JOIN pacientes ON pacientes.id = consultas.paciente_id
`);
console.log(comPaciente.all());
// [ { nome: 'Ana', dia: '2026-08-27', hora: '10:00' }, ... ]

// LEFT JOIN: todos os pacientes, mesmo os sem consulta (dia = null)
const todos = db.prepare(`
  SELECT pacientes.nome, consultas.dia
  FROM pacientes
  LEFT JOIN consultas ON consultas.paciente_id = pacientes.id
`);
console.log(todos.all());
// [ { nome: 'Ana', dia: '2026-08-27' }, { nome: 'Beto', dia: null } ]

import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('clinica.db');

// 1. As duas tabelas. Repare: consultas NÃO tem a coluna nome —
//    guardamos só paciente_id. Se Ana mudar de nome, corrigimos
//    em UM lugar (pacientes), e todos os relatórios atualizam.
db.exec(`CREATE TABLE IF NOT EXISTS pacientes (
  id INTEGER PRIMARY KEY,
  nome TEXT NOT NULL
)`);
db.exec(`CREATE TABLE IF NOT EXISTS consultas (
  id INTEGER PRIMARY KEY,
  paciente_id INTEGER NOT NULL,
  dia TEXT NOT NULL,
  hora TEXT NOT NULL
)`);

// 2. Alguns dados para o exemplo
db.exec(`INSERT INTO pacientes (id, nome) VALUES (1, 'Ana'), (2, 'Beto'), (3, 'Caio')`);
db.exec(`INSERT INTO consultas (paciente_id, dia, hora) VALUES
  (1, '2026-08-27', '10:00'), (2, '2026-08-27', '11:00')`);

// 3. Agenda do dia: JOIN junta consulta + paciente numa linha só.
//    Quem nunca veio (Caio) não aparece — INNER só acha pares.
const agenda = db.prepare(`
  SELECT consultas.hora, pacientes.nome
  FROM consultas
  INNER JOIN pacientes ON pacientes.id = consultas.paciente_id
  WHERE consultas.dia = '2026-08-27'
`);
console.log(agenda.all());
// [ { hora: '10:00', nome: 'Ana' }, { hora: '11:00', nome: 'Beto' } ]

// 4. LEFT JOIN: TODOS os pacientes; quem não tem consulta fica com null.
//    O WHERE ... IS NULL filtra justamente os órfãos.
const quemNuncaVeio = db.prepare(`
  SELECT pacientes.nome, consultas.id
  FROM pacientes
  LEFT JOIN consultas ON consultas.paciente_id = pacientes.id
  WHERE consultas.id IS NULL
`);
console.log(quemNuncaVeio.all());
// [ { nome: 'Caio', id: null } ] — o paciente esquecido
